    struct FakeFirstEventChild {
        polls: std::collections::VecDeque<Result<Option<i32>, &'static str>>,
        waits: usize,
    }

    #[test]
    fn first_event_owner_wait_exits_before_deadline_without_kill() {
        let started = Instant::now();
        let clock = std::cell::Cell::new(started);
        let killed = std::cell::Cell::new(0);
        let mut child = FakeFirstEventChild {
            polls: [Ok(None), Ok(Some(7))].into(),
            waits: 0,
        };

        let result = wait_for_first_event_owner(
            &mut child,
            5050,
            started + std::time::Duration::from_secs(1),
            |child| child.polls.pop_front().unwrap(),
            |child| {
                child.waits += 1;
                Ok(9)
            },
            |_| killed.set(killed.get() + 1),
            || clock.get(),
            |duration| clock.set(clock.get() + duration),
        );

        assert_eq!(result, FirstEventOwnerWait::Exited(7));
        assert_eq!(killed.get(), 0);
        assert_eq!(child.waits, 0);
    }

    #[test]
    fn first_event_owner_wait_kills_once_at_deadline_then_reaps() {
        let started = Instant::now();
        let clock = std::cell::Cell::new(started);
        let killed = std::cell::Cell::new(0);
        let mut child = FakeFirstEventChild {
            polls: [Ok(None), Ok(None)].into(),
            waits: 0,
        };

        let result = wait_for_first_event_owner(
            &mut child,
            5151,
            started + FIRST_EVENT_WAIT_POLL_INTERVAL,
            |child| child.polls.pop_front().unwrap(),
            |child| {
                child.waits += 1;
                Ok(11)
            },
            |pid| {
                assert_eq!(pid, 5151);
                killed.set(killed.get() + 1);
            },
            || clock.get(),
            |duration| clock.set(clock.get() + duration),
        );

        assert_eq!(result, FirstEventOwnerWait::TimedOut(Some(11)));
        assert_eq!(killed.get(), 1);
        assert_eq!(child.waits, 1);
    }

    #[test]
    fn first_event_owner_wait_error_does_not_kill_or_reap() {
        let started = Instant::now();
        let killed = std::cell::Cell::new(0);
        let mut child = FakeFirstEventChild {
            polls: [Err("try_wait failed")].into(),
            waits: 0,
        };

        let result = wait_for_first_event_owner(
            &mut child,
            5252,
            started,
            |child| child.polls.pop_front().unwrap(),
            |child| {
                child.waits += 1;
                Ok(13)
            },
            |_| killed.set(killed.get() + 1),
            || started,
            |_| panic!("try_wait errors must not sleep"),
        );

        assert_eq!(result, FirstEventOwnerWait::WaitError);
        assert_eq!(killed.get(), 0);
        assert_eq!(child.waits, 0);
    }

    struct FakeFinalizerOwner {
        polls: std::collections::VecDeque<Result<bool, &'static str>>,
        waits: usize,
    }

    #[test]
    fn finalizer_owner_wait_finishes_before_deadline_without_kill() {
        let started = Instant::now();
        let clock = std::cell::Cell::new(started);
        let killed = std::cell::Cell::new(0);
        let mut owner = FakeFinalizerOwner {
            polls: [Ok(false), Ok(true)].into(),
            waits: 0,
        };

        let result = finalizer_owner_wait(
            &mut owner,
            started + std::time::Duration::from_secs(1),
            |owner| owner.polls.pop_front().unwrap(),
            |owner| {
                owner.waits += 1;
                Ok::<_, &'static str>(17)
            },
            || killed.set(killed.get() + 1),
            || clock.get(),
            |duration| clock.set(clock.get() + duration),
            |outcome| outcome,
        );

        assert_eq!(result, FinalizerOwnerWait::Finished(17));
        assert_eq!(killed.get(), 0);
        assert_eq!(owner.waits, 1);
    }

    #[test]
    fn finalizer_owner_wait_timeout_kills_once_and_continues_closeout() {
        let started = Instant::now();
        let clock = std::cell::Cell::new(started);
        let killed = std::cell::Cell::new(0);
        let persisted = std::cell::Cell::new(0);
        let terminal_emitted = std::cell::Cell::new(0);
        let mut owner = FakeFinalizerOwner {
            polls: [Ok(false), Ok(false)].into(),
            waits: 0,
        };

        let result = finalizer_owner_wait(
            &mut owner,
            started + FINALIZER_OWNER_WAIT_POLL_INTERVAL,
            |owner| owner.polls.pop_front().unwrap(),
            |owner| {
                owner.waits += 1;
                Ok::<_, &'static str>(19)
            },
            || killed.set(killed.get() + 1),
            || clock.get(),
            |duration| clock.set(clock.get() + duration),
            |outcome| {
                if outcome == FinalizerOwnerWait::TimedOut {
                    persisted.set(persisted.get() + 1);
                    terminal_emitted.set(terminal_emitted.get() + 1);
                }
                outcome
            },
        );

        assert_eq!(result, FinalizerOwnerWait::TimedOut);
        assert_eq!(killed.get(), 1);
        assert_eq!(owner.waits, 0, "timeout must not enter an unbounded wait");
        assert_eq!(persisted.get(), 1, "timeout must continue to persistence");
        assert_eq!(
            terminal_emitted.get(),
            1,
            "timeout must continue to the terminal release"
        );
    }

