    fn borrow_lead_capable_profile(id: &str) -> db::AgentProfile {
        // agent_profile() 默认 access="borrow"。
        let mut profile = agent_profile(id, true, false);
        profile.provider = "deepseek".to_string();
        profile
    }

    fn harness_lead_capable_profile(id: &str) -> db::AgentProfile {
        let mut profile = agent_profile(id, true, false);
        profile.access = "harness".to_string();
        profile.provider = "deepseek".to_string();
        profile.endpoint = Some("https://api.deepseek.com/v1".to_string());
        profile.primary_model = Some("deepseek-chat".to_string());
        profile
    }

    #[test]
    fn should_seed_goal_p1_1_resume_without_message_never_seeds() {
        // P1-①（opus 对抗审）核心钉子：message=None（try_resume_pending 续跑路径）即使
        // 会话没有既存 goal，也绝不该 seed——不然占位兜底文案会被永久写进 goal memory
        // block。变异测试：把 `should_seed_goal` 里的 `has_message` 条件删掉/永真化，
        // 这条测试立刻变红。
        assert!(!should_seed_goal(false, false));
    }

    #[test]
    fn should_seed_goal_first_real_message_seeds_when_no_existing_goal() {
        // 真实首轮消息路径（message=Some）行为不变：没有既存 goal 时正常 seed。
        assert!(should_seed_goal(false, true));
    }

    #[test]
    fn should_seed_goal_never_reseeds_when_goal_already_exists() {
        // 已有 goal 时无论 message 有没有都不 clobber。
        assert!(!should_seed_goal(true, true));
        assert!(!should_seed_goal(true, false));
    }

    #[test]
    fn lead_engine_for_profile_native_claude_ignores_cap_lead() {
        // native claude 从不看 cap_lead（无论有值还是 NULL）。
        let mut profile = lead_capable_profile("native-claude-cap");
        assert_eq!(
            lead_engine_for_profile(&profile),
            Ok(LeadEngine::NativeClaude)
        );
        profile.cap_lead = None;
        assert_eq!(
            lead_engine_for_profile(&profile),
            Ok(LeadEngine::NativeClaude)
        );
    }

    #[test]
    fn lead_engine_for_profile_borrow_ignores_cap_lead() {
        // L1b 拍板：「能不能当 lead」是代码级属性，不读 cap_lead——存量 borrow agent 的
        // cap_lead 全 NULL 也必须放行，有值同样放行（不因为标了才行）。
        let mut profile = borrow_lead_capable_profile("borrow-lead-nullcap");
        profile.cap_lead = None;
        assert_eq!(
            lead_engine_for_profile(&profile),
            Ok(LeadEngine::BorrowClaude)
        );
        profile.cap_lead = Some("borrow_claude".to_string());
        assert_eq!(
            lead_engine_for_profile(&profile),
            Ok(LeadEngine::BorrowClaude)
        );
    }

    #[test]
    fn lead_engine_for_profile_codex_native_errs_not_supported() {
        // 哪怕用户手填了 cap_lead，L1 spawn 接不住 codex——门禁不能放行。
        let mut profile = native_codex_profile("codex-native-cap");
        profile.cap_lead = Some("someone_filled_this_in".to_string());
        let err = lead_engine_for_profile(&profile).unwrap_err();
        assert!(
            err.starts_with("AL_ERR:lead.engineNotSupported:"),
            "expected lead.engineNotSupported envelope, got: {err}"
        );
    }

    #[test]
    fn lead_engine_for_profile_harness_ignores_cap_lead() {
        // L3 A1：harness（myagent 引擎）现在可以当队长——与 borrow 同样不看 cap_lead，
        // provider 是「哪个 LLM 供应商」（deepseek/glm/...），与「能不能当 lead」无关。
        let mut profile = harness_lead_capable_profile("harness-lead-nullcap");
        profile.cap_lead = None;
        assert_eq!(lead_engine_for_profile(&profile), Ok(LeadEngine::Harness));
        profile.cap_lead = Some("whatever".to_string());
        assert_eq!(lead_engine_for_profile(&profile), Ok(LeadEngine::Harness));
    }

    fn insert_agent(conn: &Connection, profile: db::AgentProfile) {
        db::upsert_agent(conn, &profile).unwrap();
    }

    struct TestHomeGuard {
        old: Option<std::ffi::OsString>,
    }

    impl TestHomeGuard {
        fn set(path: &std::path::Path) -> Self {
            let old = std::env::var_os("HOME");
            std::env::set_var("HOME", path);
            Self { old }
        }
    }

    impl Drop for TestHomeGuard {
        fn drop(&mut self) {
            match &self.old {
                Some(v) => std::env::set_var("HOME", v),
                None => std::env::remove_var("HOME"),
            }
        }
    }

    fn git_ok(dir: &std::path::Path, args: &[&str]) {
        let out = std::process::Command::new("git")
            .current_dir(dir)
            .args(args)
            .output()
            .unwrap();
        assert!(
            out.status.success(),
            "git {args:?} failed: {}",
            String::from_utf8_lossy(&out.stderr)
        );
    }

    fn init_test_repo(repo: &std::path::Path) {
        std::fs::create_dir_all(repo).unwrap();
        git_ok(repo, &["init", "-q"]);
        git_ok(repo, &["config", "user.email", "t@t"]);
        git_ok(repo, &["config", "user.name", "t"]);
        git_ok(repo, &["config", "commit.gpgsign", "false"]);
        std::fs::write(repo.join("seed.md"), "seed\n").unwrap();
        git_ok(repo, &["add", "seed.md"]);
        git_ok(repo, &["commit", "-qm", "seed"]);
    }

    fn setup_trashed_parent_with_trashed_child(
        repo: &std::path::Path,
        parent: &str,
        child: &str,
    ) -> Db {
        let conn = crate::test_support::mem_db();
        let namespace_id = format!("gh-{parent}");
        let repo_id = format!("repo-{parent}");
        conn.execute(
            "INSERT OR IGNORE INTO namespaces (id, kind, name, is_builtin, added_at) \
             VALUES (?1, 'github_org', 'GitHub Delete Test', 0, 0)",
            [namespace_id.as_str()],
        )
        .unwrap();
        conn.execute(
            "INSERT INTO repos (id, namespace_id, source, owner, name, path, status, added_at) \
             VALUES (?1, ?2, 'github', 'owner', 'repo', ?3, 'active', 0)",
            (
                repo_id.as_str(),
                namespace_id.as_str(),
                repo.to_str().unwrap(),
            ),
        )
        .unwrap();
        db::create_session(&conn, parent, "parent", &repo_id, &namespace_id).unwrap();
        db::create_session(&conn, child, "child", &repo_id, &namespace_id).unwrap();
        db::set_session_parent(&conn, child, Some(parent)).unwrap();
        db::set_session_continued_to(&conn, parent, Some(child)).unwrap();
        let db = Db(crate::perf_probe::TimedMutex::new(conn));
        let running = Running::default();
        delete_session_inner(&db, &running, child).unwrap();
        delete_session_inner(&db, &running, parent).unwrap();
        db
    }

    fn setup_repo_continuation_parent(
        conn: &Connection,
        repo: &std::path::Path,
        parent: &str,
        ensure_parent_workspace: bool,
    ) {
        namespaces_repo::add_namespace(conn, "ns-cont", "github_org", "Continuation", 0).unwrap();
        repos_repo::add_repo(
            conn,
            "repo-cont",
            "ns-cont",
            "github",
            Some("owner"),
            "repo",
            repo.to_str().unwrap(),
            None,
        )
        .unwrap();
        db::create_session(conn, parent, "Parent", "repo-cont", "ns-cont").unwrap();
        db::upsert_memory_block(conn, parent, "goal", "Parent goal", None, Some("lead")).unwrap();
        db::upsert_memory_block(conn, parent, "state", "Parent state", None, Some("lead")).unwrap();
        db::upsert_memory_block(conn, parent, "next", "Parent next", None, Some("lead")).unwrap();
        db::insert_memory_entry(
            conn,
            parent,
            "decision",
            "Parent decision",
            "[]",
            "[]",
            Some("lead"),
            Some("high"),
            false,
        )
        .unwrap();
        if ensure_parent_workspace && !session_is_in_place(conn, parent).unwrap() {
            worktree::ensure_workspace(parent, Some(repo), false).unwrap();
        }
    }

    fn continuation_refs_for_prefix(repo: &std::path::Path, prefix: &str) -> Vec<String> {
        let out = std::process::Command::new("git")
            .current_dir(repo)
            .args(["for-each-ref", "--format=%(refname)", prefix])
            .output()
            .unwrap();
        assert!(
            out.status.success(),
            "git for-each-ref {prefix} failed: {}",
            String::from_utf8_lossy(&out.stderr)
        );
        String::from_utf8_lossy(&out.stdout)
            .lines()
            .map(str::to_string)
            .collect()
    }

    #[test]
    fn continuation_start_rejects_existing_continuation_without_child_artifacts() {
        let _home_lock = crate::worktree::test_home_lock();
        let home = tempfile::tempdir().unwrap();
        let _home_guard = TestHomeGuard::set(home.path());
        let repo_tmp = tempfile::tempdir().unwrap();
        let repo = repo_tmp.path().join("repo");
        init_test_repo(&repo);
        let db = Db(crate::perf_probe::TimedMutex::new(
            crate::test_support::mem_db(),
        ));
        let running = Running::default();
        {
            let conn = db.0.lock().unwrap();
            insert_agent(&conn, lead_capable_profile("lead-cont"));
            setup_repo_continuation_parent(&conn, &repo, "parent-existing", true);
            db::create_session(&conn, "existing-child", "Child", "repo-cont", "ns-cont").unwrap();
            db::set_session_parent(&conn, "existing-child", Some("parent-existing")).unwrap();
        }
        let before_heads = continuation_refs_for_prefix(&repo, "refs/heads/agentloom");
        let before_bases = continuation_refs_for_prefix(&repo, "refs/agentloom/base");

        let err = start_continuation_session_inner(
            &db,
            &running,
            "parent-existing",
            "交接文档：existing continuation",
            None,
            |_, _, _, _| Ok(()),
            |_, _, _| Ok(()),
        )
        .unwrap_err();

        assert!(err.contains("CONTINUATION_ALREADY_EXISTS"), "{err}");
        assert_eq!(
            continuation_refs_for_prefix(&repo, "refs/heads/agentloom"),
            before_heads
        );
        assert_eq!(
            continuation_refs_for_prefix(&repo, "refs/agentloom/base"),
            before_bases
        );
        let conn = db.0.lock().unwrap();
        let count: i64 = conn
            .query_row("SELECT COUNT(*) FROM sessions", [], |r| r.get(0))
            .unwrap();
        assert_eq!(count, 2);
        let continued: Option<String> = conn
            .query_row(
                "SELECT continued_to_session_id FROM sessions WHERE id = 'parent-existing'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(continued, None);
    }

